import{_ as e,C as a,o as n,c as s,j as o,a as l,E as r,a2 as i}from"./chunks/framework.DGvnA5EY.js";const u="/workbuddy-guide/assets/25-hei-reliability.BVbsZO0S.png",k=JSON.parse('{"title":"第 25 章 自动化工作流的可靠性","description":"> 内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利） 自动化任务第一次跑成功，你会有种\\"解放了\\"的错觉。真正的考验在第二周：网页改版了、 文件挪位置了、定时任务静默失败了三天没人发现——等你发现时，活已经断了一周。","frontmatter":{"title":"第 25 章 自动化工作流的可靠性"},"headers":[],"relativePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 25 章 自动化工作流的可靠性/index.md","filePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 25 章 自动化工作流的可靠性/index.md","lastUpdated":1791629861000}'),p={name:"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 25 章 自动化工作流的可靠性/index.md"};function b(g,t,h,q,m,_){const d=a("Paywall");return n(),s("div",null,[t[0]||(t[0]=o("h1",{id:"第-25-章-自动化工作流的可靠性",tabindex:"-1"},[l("第 25 章 自动化工作流的可靠性 "),o("a",{class:"header-anchor",href:"#第-25-章-自动化工作流的可靠性","aria-label":'Permalink to "第 25 章 自动化工作流的可靠性"'},"​")],-1)),t[1]||(t[1]=o("blockquote",null,[o("p",null,"内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利）")],-1)),r(d,{part:"3",variant:"banner"}),t[2]||(t[2]=i('<p>自动化任务第一次跑成功，你会有种&quot;解放了&quot;的错觉。真正的考验在第二周：网页改版了、 文件挪位置了、定时任务静默失败了三天没人发现——<strong>等你发现时，活已经断了一周</strong>。</p><p>这一章讲的就是：怎么让自动化&quot;跑一百次不出事，出了事立刻有人知道&quot;。 这是把 AI 工作流从&quot;玩具&quot;变成&quot;系统&quot;的最后一公里。</p><p><img src="'+u+'" alt="一只小黑盯着屏幕上的心跳曲线，手里拿着检查清单" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解本章主题，与实际软件界面无关。</em></p><h2 id="一、自动化的三种典型死法" tabindex="-1">一、自动化的三种典型死法 <a class="header-anchor" href="#一、自动化的三种典型死法" aria-label="Permalink to &quot;一、自动化的三种典型死法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>死法</th><th>现象</th><th>典型原因</th></tr></thead><tbody><tr><td><strong>静默失败</strong></td><td>没跑，但没人知道没跑</td><td>定时配置错、进程崩溃、通知没配</td></tr><tr><td><strong>数据漂移</strong></td><td>跑了，但产出是错的</td><td>网页改版、字段更名、文件挪了位置</td></tr><tr><td><strong>重复副作用</strong></td><td>跑了，但跑重了</td><td>同一时段触发两次、重试导致重复发送/建文件</td></tr></tbody></table><p>第一种最危险——因为它最安静。<strong>可靠性设计的核心目标：把三种死法都变成 &quot;会喊疼的伤口&quot;，而不是&quot;无痛的内出血&quot;。</strong></p><h2 id="二、五条设计原则-对照表自查" tabindex="-1">二、五条设计原则（对照表自查） <a class="header-anchor" href="#二、五条设计原则-对照表自查" aria-label="Permalink to &quot;二、五条设计原则（对照表自查）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原则</th><th>一句话解释</th><th>自查问题</th></tr></thead><tbody><tr><td><strong>幂等</strong></td><td>同一任务重跑一遍，结果不变、不产生副作用</td><td>重跑会不会发两条一样的消息、建两个同名文件？</td></tr><tr><td><strong>可观测</strong></td><td>每次运行都留下&quot;我跑了、我成功了&quot;的痕迹</td><td>断跑三天，你多久会发现？</td></tr><tr><td><strong>可恢复</strong></td><td>失败后能从断点续跑，不用从头再来</td><td>上次失败后，你是删掉重做还是接着做？</td></tr><tr><td><strong>最小权限</strong></td><td>自动化只用完成它所需的权限</td><td>它有权限删东西吗？有权限对外发消息吗？</td></tr><tr><td><strong>先手动后自动</strong></td><td>手动成功跑过 10 次的流程，才值得自动化</td><td>这个流程你手动做过几次？</td></tr></tbody></table><blockquote><p><strong>&quot;先手动后自动&quot;是新手最容易跳过的一条</strong>。流程本身没跑稳就自动化， 等于把错误固化成每天定时出错。</p></blockquote>',10)),r(d,{part:"3"}),t[3]||(t[3]=o("p",null,[o("em",null,"—— 以上试读到此为止。第三篇共 4 章，完整版（飞书文档）包含全部实操内容。——")],-1))])}const x=e(p,[["render",b]]);export{k as __pageData,x as default};
